// Extract webhook payload
const payload = $input.first().json;

console.log('=== FRONTEND SECTION GENERATION REQUEST ===');
console.log('Company ID:', payload.companyId);
console.log('Section ID:', payload.sectionId);
console.log('Section Name:', payload.sectionName);
console.log('Section Column:', payload.sectionColumn);
console.log('Previous Sections Count:', payload.previousSections?.length || 0);

// Validate required fields
if (!payload.companyId || !payload.sectionId || !payload.sectionColumn) {
  throw new Error('Missing required fields: companyId, sectionId, or sectionColumn');
}

// Build context from previous sections
let contextText = '';
if (payload.previousSections && payload.previousSections.length > 0) {
  contextText = payload.previousSections
    .map(section => `${section.name}:\n${section.content}`)
    .join('\n\n---\n\n');
  console.log('Context sections available:', payload.previousSections.length);
}

// Generate prompt for AI
const prompt = `You are a professional due diligence analyst. Generate comprehensive content for the "${payload.sectionName}" section of a due diligence report.

${contextText ? `Context from previous sections:\n${contextText}\n\n` : ''}

Please generate detailed, professional content for this section. The content should be:
1. Comprehensive and thorough
2. Professional in tone
3. Well-structured with clear headings
4. Relevant to the section's purpose
${contextText ? '5. Building upon insights from previous sections' : ''}

Generate the content in HTML format for proper display.`;

return {
  json: {
    companyId: payload.companyId,
    sectionId: payload.sectionId,
    sectionName: payload.sectionName,
    sectionColumn: payload.sectionColumn,
    prompt: prompt,
    contextAvailable: !!contextText,
    previousSectionsCount: payload.previousSections?.length || 0
  }
};

